import Dexie, { Table } from 'dexie';

class AthenaDatabase extends Dexie {
  topics!: Table<Topic, string>;
  messages!: Table<Message, string>;
  predefinedPrompts!: Table<PredefinedPrompt, string>;
  userSettings!: Table<UserSetting, string>;

  constructor() {
    super('AthenaDatabase');

    this.version(1).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted',
      messages: 'id, topicId, type, created, isDeleted, includeInContext',
      usages: 'id, messageId',
    });

    this.version(2)
      .stores({
        topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId',
        messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext',
      })
      .upgrade(async (trans) => {
        try {
          const DEFAULT_FORK_ID = 'main';

          // Migrate topics
          await trans
            .table('topics')
            .toCollection()
            .modify((topic: Topic) => {
              if (!topic.forks) {
                topic.forks = [
                  {
                    id: DEFAULT_FORK_ID,
                    name: 'Main',
                    createdOn: topic.createdOn,
                  },
                ];
                topic.activeForkId = DEFAULT_FORK_ID;
              }
            });

          // Migrate messages
          await trans
            .table('messages')
            .toCollection()
            .modify((message: Message) => {
              if (!message.forkId) {
                message.forkId = DEFAULT_FORK_ID;
              }
            });
        } catch (err) {
          console.error('[migration-error] AthenaDb v2 migration failed', err);
          throw err;
        }
      });

    // Version 3 was never shipped; this stub ensures a clean upgrade path
    // for any database that somehow landed on schema version 3.
    this.version(3).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext',
    });

    this.version(4).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
    });

    this.version(5)
      .stores({
        messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      })
      .upgrade(async (trans) => {
        try {
          const allMessages = (await trans.table('messages').toArray()) as Message[];

          // Sort by topic and created time
          const sorted = allMessages.sort((a, b) => {
            if (a.topicId !== b.topicId) return a.topicId.localeCompare(b.topicId);
            return new Date(a.created).getTime() - new Date(b.created).getTime();
          });

          const updates: { id: string; parentMessageId: string }[] = [];
          const lastUserMessageByTopic = new Map<string, string>();

          for (const m of sorted) {
            if (m.type === 'user') {
              lastUserMessageByTopic.set(m.topicId, m.id);
            } else if (m.type === 'assistant' && !m.parentMessageId) {
              const parentId = lastUserMessageByTopic.get(m.topicId);
              if (parentId) {
                updates.push({ id: m.id, parentMessageId: parentId });
              }
            }
            // aiNote / system messages do not reset the last-user-message tracking
          }

          for (const update of updates) {
            await trans.table('messages').update(update.id, { parentMessageId: update.parentMessageId });
          }
        } catch (err) {
          console.error('[migration-error] AthenaDb v5 migration failed', err);
          throw err;
        }
      });

    this.version(6).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
    });

    // Version 7: add embedding field to messages (no new index needed)
    this.version(7).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
    });

    // Version 8: add mode index to topics for debate mode
    this.version(8).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
    });

    // Version 9: add modelId index to topics for per-chat model memory,
    // and backfill existing topics from the last assistant message with a model.
    this.version(9)
      .stores({
        topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
        messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
        predefinedPrompts: 'id, name',
        userSettings: 'id',
      })
      .upgrade(async (trans) => {
        try {
          const allMessages = (await trans.table('messages').toArray()) as Message[];

          // Find the last (most recent) assistant message per topic that has a model
          const lastModelByTopic = new Map<string, string>();
          const lastCreatedByTopic = new Map<string, string>();

          for (const m of allMessages) {
            if (m.type === 'assistant' && m.model) {
              const prevCreated = lastCreatedByTopic.get(m.topicId);
              const prevModel = lastModelByTopic.get(m.topicId);
              if (!prevCreated || m.created > prevCreated || (m.created === prevCreated && m.id > (prevModel ?? ''))) {
                lastCreatedByTopic.set(m.topicId, m.created);
                lastModelByTopic.set(m.topicId, m.model);
              }
            }
          }

          // Update only topics that don't already have a modelId
          const allTopics = (await trans.table('topics').toArray()) as Topic[];
          for (const topic of allTopics) {
            const modelId = lastModelByTopic.get(topic.id);
            if (modelId && !topic.modelId) {
              await trans.table('topics').update(topic.id, { modelId });
            }
          }
        } catch (err) {
          console.error('[migration-error] AthenaDb v9 migration failed', err);
          throw err;
        }
      });

    // Version 10: add summaryTokens and summaryCost fields to messages (no new index needed)
    this.version(10).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
    });

    // Version 11: add summaryReadCount field to messages (no new index needed)
    this.version(11)
      .stores({
        topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
        messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
        predefinedPrompts: 'id, name',
        userSettings: 'id',
      })
      .upgrade(async (trans) => {
        try {
          await trans
            .table('messages')
            .toCollection()
            .modify((msg: Message) => {
              if (msg.summary && msg.summaryReadCount === undefined) {
                msg.summaryReadCount = 0;
              }
            });
        } catch (err) {
          console.error('[migration-error] AthenaDb v11 migration failed', err);
          throw err;
        }
      });

    // Version 12: add analyticsSnapshots table for time-based analytics
    this.version(12).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
      analyticsSnapshots: 'date',
    });

    // Version 13: add learningCycles and learningDays tables for Curator mode
    this.version(13).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
      analyticsSnapshots: 'date',
      learningCycles: 'id, topicId, phase, weekStart',
      learningDays: 'id, cycleId, dayNumber',
    });

    // Version 14: convert stored costs from SEK to USD (canonical base currency).
    // The old hardcoded exchange rate was USD_TO_SEK = 10.
    this.version(14)
      .stores({
        topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
        messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
        predefinedPrompts: 'id, name',
        userSettings: 'id',
        analyticsSnapshots: 'date',
        learningCycles: 'id, topicId, phase, weekStart',
        learningDays: 'id, cycleId, dayNumber',
      })
      .upgrade(async (trans) => {
        try {
          const SEK_TO_USD = 1 / 10;
          await trans
            .table('messages')
            .toCollection()
            .modify((msg: Message) => {
              if (typeof msg.totalCost === 'number') {
                msg.totalCost = msg.totalCost * SEK_TO_USD;
              }
              if (typeof msg.summaryCost === 'number') {
                msg.summaryCost = msg.summaryCost * SEK_TO_USD;
              }
            });
          await trans
            .table('analyticsSnapshots')
            .toCollection()
            .modify((snap: AnalyticsSnapshot) => {
              if (typeof snap.cost === 'number') {
                snap.cost = snap.cost * SEK_TO_USD;
              }
              if (snap.providerStats) {
                for (const key of Object.keys(snap.providerStats)) {
                  const stat = snap.providerStats[key];
                  if (typeof stat.cost === 'number') {
                    stat.cost = stat.cost * SEK_TO_USD;
                  }
                }
              }
            });
        } catch (err) {
          console.error('[migration-error] AthenaDb v14 migration failed', err);
          throw err;
        }
      });

    // Version 15: add checklistGroups and checklistItems tables for Checklist mode
    this.version(15).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
      analyticsSnapshots: 'date',
      learningCycles: 'id, topicId, phase, weekStart',
      learningDays: 'id, cycleId, dayNumber',
      checklistGroups: 'id, topicId, sortOrder',
      checklistItems: 'id, groupId, sortOrder',
    });

    // Version 16: add checklistHistory table for checklist instruction continuity
    this.version(16).stores({
      topics: 'id, userId, name, createdOn, updatedOn, isDeleted, activeForkId, maxContextMessages, mode, modelId',
      messages: 'id, topicId, forkId, type, created, isDeleted, includeInContext, parentMessageId',
      predefinedPrompts: 'id, name',
      userSettings: 'id',
      analyticsSnapshots: 'date',
      learningCycles: 'id, topicId, phase, weekStart',
      learningDays: 'id, cycleId, dayNumber',
      checklistGroups: 'id, topicId, sortOrder',
      checklistItems: 'id, groupId, sortOrder',
      checklistHistory: 'id, topicId, seq',
    });
  }

  analyticsSnapshots!: Table<AnalyticsSnapshot, string>;
  learningCycles!: Table<LearningCycle, string>;
  learningDays!: Table<LearningDay, string>;
  checklistGroups!: Table<ChecklistGroup, string>;
  checklistItems!: Table<ChecklistItem, string>;
  checklistHistory!: Table<ChecklistHistoryEntry, string>;
}

export type MessageType = 'user' | 'assistant' | 'system' | 'aiNote';

export interface Attachment {
  id: string;
  name: string;
  type: string;
  size: number;
  data: string; // base64
  previewUrl?: string; // for images
}

export interface Fork {
  id: string;
  name: string;
  createdOn: string;
}

export interface PredefinedPrompt {
  id: string;
  name: string;
  content: string;
}

export interface UserSetting {
  id: string;
  value: unknown;
}

export type DebateSide = 'left' | 'right';
export type DebatePhase = 'answer' | 'review' | 'final' | 'consensus';

export interface Message {
  id: string;
  topicId: string;
  forkId?: string;
  type: MessageType;
  content: string;
  model?: string;
  isDeleted: boolean;
  includeInContext: boolean;
  isClarification?: boolean;
  created: string;
  failed: boolean;
  promptTokens: number;
  completionTokens: number;
  cachedTokens?: number;
  cacheCreationTokens?: number;
  totalCost: number;
  searchCount?: number;
  latencyMs?: number;
  reasoning?: string;
  toolLogs?: string;
  parentMessageId?: string;
  activeResponseId?: string;
  attachments?: Attachment[];
  embedding?: number[] | null;
  summary?: string;
  summaryTokens?: number;
  summaryCost?: number;
  summaryReadCount?: number;
  rawResponse?: string;
  // Debate fields
  debateSide?: DebateSide;
  debatePhase?: DebatePhase;
}

export type TopicMode = 'topic' | 'debate' | 'curator' | 'checklist';

export type CuratorPhase = 'suggesting' | 'active' | 'completed' | 'rated';

export interface ReflectionQuestion {
  question: string;
  answer: string;
}

export interface LearningCycle {
  id: string;
  topicId: string;
  topicName: string;
  hook: string;
  weekStart: string;
  phase: CuratorPhase;
  topicRating?: number;
  contentRating?: number;
  reflections?: string;
  priorKnowledgeLevel?: 'beginner' | 'intermediate' | 'advanced';
}

export interface LearningDay {
  id: string;
  cycleId: string;
  dayNumber: number;
  subTopic: string;
  hook: string;
  opener: string;
  summary: string;
  links: string[];
  bridge: string;
  keyTakeaway: string;
  hookArchetype: string;
  estimatedReadingMinutes: number;
  reflectionQuestions: ReflectionQuestion[];
  isCompleted: boolean;
}

export interface ChecklistGroup {
  id: string;
  topicId: string;
  title: string;
  sortOrder: number;
}

export interface ChecklistItem {
  id: string;
  groupId: string;
  content: string;
  details?: string;
  checked: boolean;
  sortOrder: number;
  createdBy?: 'user' | 'assistant';
}

export interface ChecklistHistoryEntry {
  id: string;
  topicId: string;
  role: 'user' | 'assistant';
  content: string;
  created: string;
  seq: number;
}

export interface Topic {
  id: string;
  name: string;
  createdOn: string;
  updatedOn: string;
  isDeleted: boolean;
  scratchpad?: string;
  forks?: Fork[];
  activeForkId?: string;
  maxContextMessages?: number;
  selectedPromptIds?: string[];
  modelId?: string;
  // Debate fields
  mode?: TopicMode;
  debateModelAId?: string;
  debateModelBId?: string;
}

export interface AnalyticsSnapshot {
  date: string; // 'YYYY-MM-DD'
  messageCount: number;
  failedCount: number;
  promptTokens: number;
  completionTokens: number;
  cost: number;
  latencySamples?: number[];
  providerStats?: Record<string, { cost: number; tokens: number; messageCount: number }>;
  toolStats?: Record<string, { calls: number; successCount: number; errors: string[] }>;
}

export const athenaDb = new AthenaDatabase();
